//! Bluetooth profile-driver DDI bindings (bthdef.h, bthsdpdef.h, bthioctl.h,
//! bthddi.h). Types/constants are bindgen-generated by build.rs; the items
//! bindgen cannot produce (CTL_CODE macros, DEFINE_GUID) are hand-written
//! below. All of it is cross-checked against MSVC: `tools/bthcheck` compiles
//! a C program with cl.exe against the same WDK headers and its output is
//! frozen in `tools/bthcheck/msvc-layout.txt`; the `const` asserts at the
//! bottom encode those exact numbers, so a mismatch fails the driver build.
#![allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    unused_imports,
    missing_docs,
    unnecessary_transmutes,
    clippy::all
)]

use wdk_sys::*;

include!(concat!(env!("OUT_DIR"), "/bth.rs"));

/// `{94A59AA8-4383-4286-AA4F-34A160F40004}` (bthguid.h)
pub const GUID_BTHDDI_PROFILE_DRIVER_INTERFACE: GUID = GUID {
    Data1: 0x94a5_9aa8,
    Data2: 0x4383,
    Data3: 0x4286,
    Data4: [0xaa, 0x4f, 0x34, 0xa1, 0x60, 0xf4, 0x00, 0x04],
};


const FILE_DEVICE_BLUETOOTH: u32 = 0x41;
const METHOD_NEITHER: u32 = 3;
const fn bth_kernel_ctl(id: u32) -> u32 {
    (FILE_DEVICE_BLUETOOTH << 16) | (id << 2) | METHOD_NEITHER
}
/// bthioctl.h; MSVC value 0x00410003.
pub const IOCTL_INTERNAL_BTH_SUBMIT_BRB: u32 = bth_kernel_ctl(0x00);
/// bthioctl.h; MSVC value 0x0041000B. Output: BTH_DEVICE_INFO.
pub const IOCTL_INTERNAL_BTHENUM_GET_DEVINFO: u32 = bth_kernel_ctl(0x02);

/// `DEVPKEY_Device_InstanceId` {78c34fc8-104a-4aca-9ea4-524d52996e57}, 256
pub const DEVPKEY_DEVICE_INSTANCE_ID: DEVPROPKEY = DEVPROPKEY {
    fmtid: GUID {
        Data1: 0x78c3_4fc8,
        Data2: 0x104a,
        Data3: 0x4aca,
        Data4: [0x9e, 0xa4, 0x52, 0x4d, 0x52, 0x99, 0x6e, 0x57],
    },
    pid: 256,
};

/// `DEVPKEY_Device_FriendlyName` {a45c254e-df1c-4efd-8020-67d146a850e0}, 14
/// (devpkey.h; value printed by tools/acxcheck).
pub const DEVPKEY_DEVICE_FRIENDLY_NAME: DEVPROPKEY = DEVPROPKEY {
    fmtid: GUID {
        Data1: 0xa45c_254e,
        Data2: 0xdf1c,
        Data3: 0x4efd,
        Data4: [0x80, 0x20, 0x67, 0xd1, 0x46, 0xa8, 0x50, 0xe0],
    },
    pid: 14,
};

// ---- MSVC layout (tools/bthcheck/msvc-layout.txt) -------------------------
use core::mem::{offset_of, size_of};
const _: () = {
    assert!(BTHDDI_PROFILE_DRIVER_INTERFACE_VERSION_FOR_QI == 0x0200);
    assert!(IOCTL_INTERNAL_BTH_SUBMIT_BRB == 0x0041_0003);
    assert!(IOCTL_INTERNAL_BTHENUM_GET_DEVINFO == 0x0041_000B);
    assert!(size_of::<BRB_HEADER>() == 112);
    assert!(size_of::<_BRB>() == 480);
    assert!(size_of::<_BRB_L2CA_OPEN_CHANNEL>() == 368);
    assert!(size_of::<_BRB_L2CA_CLOSE_CHANNEL>() == 128);
    assert!(size_of::<_BRB_L2CA_ACL_TRANSFER>() == 168);
    assert!(size_of::<BTH_DEVICE_INFO>() == 272);
    assert!(size_of::<BTH_PROFILE_DRIVER_INTERFACE>() == 72);
    assert!(size_of::<INDICATION_PARAMETERS>() == 232);
    assert!(offset_of!(BRB_HEADER, Length) == 16);
    assert!(offset_of!(BRB_HEADER, Type) == 22);
    assert!(offset_of!(BRB_HEADER, Status) == 28);
    assert!(offset_of!(BRB_HEADER, BtStatus) == 32);
    assert!(offset_of!(BRB_HEADER, ClientContext) == 72);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, ChannelHandle) == 112);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, __bindgen_anon_1) == 120); // Psm
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, ChannelFlags) == 124);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, BtAddress) == 128);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, ConfigOut) == 136);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, ConfigIn) == 200);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, CallbackFlags) == 216);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, Callback) == 224);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, CallbackContext) == 232);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, ReferenceObject) == 240);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, OutResults) == 248);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, InResults) == 304);
    assert!(offset_of!(_BRB_L2CA_OPEN_CHANNEL, IncomingQueueDepth) == 360);
    assert!(offset_of!(_BRB_L2CA_ACL_TRANSFER, ChannelHandle) == 120);
    assert!(offset_of!(_BRB_L2CA_ACL_TRANSFER, TransferFlags) == 128);
    assert!(offset_of!(_BRB_L2CA_ACL_TRANSFER, BufferSize) == 132);
    assert!(offset_of!(_BRB_L2CA_ACL_TRANSFER, Buffer) == 136);
    assert!(offset_of!(_BRB_L2CA_ACL_TRANSFER, BufferMDL) == 144);
    assert!(offset_of!(_BRB_L2CA_ACL_TRANSFER, Timeout) == 152);
    assert!(offset_of!(_BRB_L2CA_ACL_TRANSFER, RemainingBufferSize) == 160);
    assert!(offset_of!(_BRB_L2CA_CLOSE_CHANNEL, BtAddress) == 112);
    assert!(offset_of!(_BRB_L2CA_CLOSE_CHANNEL, ChannelHandle) == 120);
    assert!(offset_of!(BTH_DEVICE_INFO, flags) == 0);
    assert!(offset_of!(BTH_DEVICE_INFO, address) == 8);
    assert!(offset_of!(BTH_DEVICE_INFO, classOfDevice) == 16);
    assert!(offset_of!(BTH_DEVICE_INFO, name) == 20);
    assert!(offset_of!(BTH_PROFILE_DRIVER_INTERFACE, BthAllocateBrb) == 32);
    assert!(offset_of!(BTH_PROFILE_DRIVER_INTERFACE, BthFreeBrb) == 40);
    assert!(offset_of!(BTH_PROFILE_DRIVER_INTERFACE, BthInitializeBrb) == 48);
    assert!(offset_of!(BTH_PROFILE_DRIVER_INTERFACE, BthReuseBrb) == 56);
    assert!(offset_of!(INDICATION_PARAMETERS, ConnectionHandle) == 0);
    assert!(offset_of!(INDICATION_PARAMETERS, BtAddress) == 8);
    assert!(offset_of!(INDICATION_PARAMETERS, Parameters) == 16);
};
